<section class="page-hero shell compact"><span class="kicker">ÁREA PERSONAL</span><h1>Mis <em>pedidos.</em></h1><p>Consulta tus vehículos y el estado actual de fabricación de cada pedido.</p><a class="btn btn-primary" href="/configurador">Crear nuevo diseño ↗</a></section><section class="section shell"><div class="section-heading"><h2>Historial de encargos</h2><span><?= count($orders) ?> pedidos</span></div><?php if (!$orders): ?><div class="empty-state surface"><strong>No tienes pedidos todavía.</strong><p>Empieza personalizando tu primer vehículo.</p><a class="btn btn-primary" href="/configurador">Configurar vehículo ↗</a></div><?php else: ?><div class="order-grid"><?php foreach ($orders as $order): ?><?php $ratio = round(100 * (int) $order['done_steps'] / 7); ?><a class="order-card surface" href="/pedidos/<?= (int) $order['id'] ?>"><div class="order-top"><span class="card-overline">PEDIDO #<?= (int) $order['id'] ?></span><span class="status status-<?= e($order['status']) ?>"><?= e(\App\Models\Order::STATUS[$order['status']] ?? $order['status']) ?></span></div><h3>Vehículo personalizado</h3><p>Creado el <?= date_es($order['created_at']) ?></p><div class="progress-caption"><span>Fabricación</span><strong><?= $ratio ?>%</strong></div><div class="progress-track"><div class="progress-fill" style="width:<?= $ratio ?>%"></div></div><div class="order-bottom"><strong><?= money($order['total']) ?></strong><span>Ver detalles ↗</span></div></a><?php endforeach; ?></div><?php endif; ?></section>